/**
 * Writes `public/whats-new.json`: the short, French, user-facing summary of a
 * release that the in-app "what's new" popup (and the release notes) show.
 *
 * It calls the Claude Code CLI directly, in print mode, with the
 * subscription token (`CLAUDE_CODE_OAUTH_TOKEN`, generated by running
 * `claude setup-token`). The `claude-code-action` this used to go through
 * refuses the `push` event the release workflow runs on ("Unsupported event
 * type: push"), and since the step is best-effort that failure went unseen:
 * every release shipped without a changelog. Here the model only has to
 * answer with text; the file is written, and validated, by this script, so a
 * bad answer fails loudly instead of leaving nothing behind.
 *
 *   NEW_TAG=v0.6.0 COMMIT_LOG="$(git log ...)" node scripts/write-whats-new.mjs
 *
 * Env: NEW_TAG (required), COMMIT_LOG (the commits since the previous tag),
 * CLAUDE_CODE_OAUTH_TOKEN (read by the CLI itself).
 */
import { execFileSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const MODEL = 'claude-haiku-4-5'

export function buildPrompt(tag, log) {
  return `You are writing the "what's new" summary shown once to Orthobox users right after they update to a new version. Orthobox is a French-language web app used during speech-therapy sessions: a toolbox of short games for a speech therapist and their patient, often a child. Your audience is a parent, a speech therapist, or occasionally a curious teenager, never a developer.

This release is tagged ${tag}. Here are every commit's subject and body since the previous release, most recent first, each block separated by a line of three dashes:

${log}

From those commits, write a short list of highlights, each a single short French sentence, for a change a user would actually notice: a new game, a visible interface or usability improvement, or a bug fix that affected what they could do or see. Leave out anything purely internal: dependency bumps, CI or release-workflow changes, refactors, test additions, documentation, build tooling, or performance work invisible to the user. If the release has nothing a user would notice, use an empty list rather than inventing a line. Merge commits that describe facets of the same visible change into a single line rather than listing each separately.

Write in plain, warm French: one clause per idea, no jargon, no markdown, no emoji, each line capitalised and ending with a period like an ordinary sentence.

Answer with valid JSON and nothing else, with exactly this shape:
{"highlights": ["...", "..."]}`
}

/** Pulls the highlights out of the model's answer, which may wrap the JSON in
 * a code fence or a sentence. Throws if there is no usable list. */
export function extractHighlights(answer) {
  const start = answer.indexOf('{')
  const end = answer.lastIndexOf('}')
  if (start === -1 || end <= start) throw new Error('No JSON object in the answer')
  const { highlights } = JSON.parse(answer.slice(start, end + 1))
  if (!Array.isArray(highlights)) throw new Error('"highlights" is not a list')
  const lines = highlights.map((line) => (typeof line === 'string' ? line.trim() : ''))
  if (lines.some((line) => line === '')) throw new Error('"highlights" holds an empty or non-text line')
  return lines
}

export function whatsNewFor(tag, highlights) {
  return { version: tag.replace(/^v/, ''), highlights }
}

function main() {
  const tag = process.env.NEW_TAG
  if (!tag) throw new Error('NEW_TAG is required (e.g. "v0.6.0")')
  const prompt = buildPrompt(tag, process.env.COMMIT_LOG ?? '')

  const answer = execFileSync('npx', ['--yes', '@anthropic-ai/claude-code', '-p', '--model', MODEL, '--tools', ''], {
    cwd: ROOT,
    input: prompt,
    encoding: 'utf8',
    maxBuffer: 10 * 1024 * 1024,
  })
  const whatsNew = whatsNewFor(tag, extractHighlights(answer))
  writeFileSync(resolve(ROOT, 'public/whats-new.json'), `${JSON.stringify(whatsNew, null, 2)}\n`)
  console.log(`Wrote public/whats-new.json with ${whatsNew.highlights.length} highlight(s):`)
  for (const line of whatsNew.highlights) console.log(` - ${line}`)
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  try {
    main()
  } catch (error) {
    // Best-effort in the workflow (a release is never blocked by this), but
    // never silent: an error annotation shows on the run's summary page.
    console.log(`::error::Could not write the user-facing changelog: ${error.message}`)
    process.exit(1)
  }
}
